/bin/bash -lc "cd [workspace path] && python3 -c \"
from PIL import Image, ImageDraw
im = Image.open('first_frame.png').convert('RGB')
d = ImageDraw.Draw(im)
# grid every 16px
for x in range(0,256,16): d.line([(x,0),(x,192)], fill=(255,0,255), width=1)
for y in range(0,192,16): d.line([(0,y),(256,y)], fill=(255,0,255), width=1)
for x in range(0,256,32): d.text((x+1,1), str(x), fill=(0,255,255))
for y in range(0,192,32): d.text((1,y+1), str(y), fill=(0,255,255))
im.resize((256*3,192*3), Image.NEAREST).save('.tmp/grid.png')
\""
